test('terminal coherence CI coverage rejects missing, duplicate and failed cases',()=>{
 const ci=readFileSync(new URL('../../../.github/workflows/ci.yml',import.meta.url),'utf8');
 const block=ci.split('                  # TERMINAL_COHERENCE_COVERAGE_BEGIN\n')[1].split('                  # TERMINAL_COHERENCE_COVERAGE_END')[0].split('\n').map(l=>l.replace(/^ {18}/,'')).join('\n');
 const names=terminalCases.map(([name])=>'terminal coherence: '+name).concat('MAJOR-03 exact retained failure insertion rejects in receipt and enclosing audit');
 const lines=names.map((name,i)=>'ok '+(i+1)+' - '+name);
 for(const [name,tap,expected]of [['valid',lines.join('\n'),0],['missing',lines.slice(1).join('\n'),1],['duplicate',[...lines,lines[0]].join('\n'),1],['failure',lines.join('\n').replace('ok 1 -','not ok 1 -'),1]]){
  const result=spawnSync('python3',['-c','import re,sys,json\nv=json.load(sys.stdin);text=v["text"];exec(v["guard"])'],{input:JSON.stringify({guard:block,text:tap}),encoding:'utf8'});assert.equal(result.status,expected,name+': '+result.stderr);
 }
});

