// Exercise each retained outer type in the outer journal itself. Failure and
// duplicate records use actual collector emissions, never renamed happy rows.
function ownershipSweepFixture(kind){
 const c=createAdoptRequestEvidence('https://www.luiguiherrera.com'),events=[],page='page-1',origin='https://www.luiguiherrera.com';
 c.listenerStart(page);c.pageLifecycle(page,'ACTIVE');c.observability.context(transitions.T2);c.start(page,'T2');
 const a=c.action(page,'CLICK','.sl-picker-group button[title="SPDR Gold Shares"]');
 c.registerAction({...a,script_sha256:scriptFingerprint(page,'marker'),source_sha256:sha(listenerMarker),source_url_sha256:sha('https://sl-qa.invalid/action/'+a.action_instance_id)});c.beginAction(a.action_instance_id);
 c.scriptParsed(page,{scriptId:'script',hash:'a'.repeat(64),length:100,startLine:0,startColumn:0,executionContextAuxData:{isDefault:true}},events);
 const request=(redirect=false)=>c.request(page,{requestId:'request',timestamp:1,type:'Fetch',frameId:'frame',loaderId:'loader',documentURL:origin+'/niveles-estadisticos',request:{url:origin+'/asset',method:'GET',headers:{RSC:'1','Next-Router-Prefetch':'0'}},initiator:{type:'script',stack:{callFrames:[{scriptId:'marker',url:origin+'/marker.js',lineNumber:0,columnNumber:0}]}},...(redirect?{redirectResponse:{status:307}}:{})});
 request();if(kind==='REDIRECTED')request(true);
 c.response(page,{requestId:'request',timestamp:2,type:'Fetch',response:{status:200}});
 if(kind==='NATIVE_DUPLICATE')c.response(page,{requestId:'request',timestamp:2,type:'Fetch',response:{status:200}});
 if(kind==='FAILED')c.failure(page,{requestId:'request',timestamp:3,type:'Fetch',canceled:false,errorText:'net::ERR_FAILED'},0);
 else c.finished(page,{requestId:'request',timestamp:3});
 if(['APPLICATION_EXCEPTION','EXCEPTION_DUPLICATE'].includes(kind)){
  const native={exceptionDetails:{exceptionId:1}},raw={kind:'exception',source:'Runtime.exceptionThrown',url:origin+'/app.js'};
  c.exception(page,native,raw);if(kind==='EXCEPTION_DUPLICATE')c.exception(page,native,raw);
 }
 c.completeAction(a.action_instance_id,{dispatch_ack:true,event_seen:true,listener_calls:1});c.complete(page,'T2',true);
 c.pageLifecycle(page,'CLOSING');c.listenerDrain(page);c.sourceClosed(page);c.pageLifecycle(page,'CLOSED');c.freeze();
 const receipts=c.receipts(events),result=account(events,false,origin,c.admittedReceipts(receipts));
 return c.evidence(events,result,receipts);
}
